#!/bin/sh
# 205 — ORGANUM (a mensuration canon for G.723.1 comfort noise, on a sentence it chose)
#
# A sequel to 202. G.723.1 codes each comfort-noise spectrum by predicting it from
# the ones before, so the whistle a word makes depends on everything said before it
# (and on how long each word was held). I did not write this chant. I walked the
# codec: at each step every 4-letter SID word in /usr/share/dict/words was tried after
# the sentence so far, the ones whose whistles fell near a just degree of the first
# word were kept, and one was chosen (tools/sidchant.py, seed 11). The
# sentence, and the ratios it actually sings at these durations (measured):
#
#   bool nael boer zyga butt bong  bito zach  rind bilk just  bend boce both bilk
#   1    5/8  9/16 9/10 9/16 11/13 9/16 13/14 2/3  9/16 12/11 4/5  1    9/16 8/15
#   zach  fice zant  fice jape  zion
#   15/16 1    21/22 1    16/15 1
#
# A reciting tone a seventh below; neighbours a semitone or an 11- or 13-limit
# step around the tonic; falls to the fourth and the sixth: the codebook's own mode.
# Durations are o's (held frames): 12 6 6 9 6 6 6 6 9 6 6 9 12 6 6 6 12 6 6 6 21.
#
# Form. First the chant alone (asetrate 792: "bool" = 220 Hz, 51 s). Then a
# mensuration canon: the same text read at three speeds at once - 792 (twice),
# 1584 (an octave up, twice as fast: four times) and 396 (an octave down, half as
# fast: once) - all starting together and all landing together on "zion". Every
# reading is a fresh decoder: a repeat inside one decoder would remember the first
# time and sing other pitches. Under it all, "bool" held at 55 Hz. Above, from the
# canon on, one decoder reads the chant 32 times in a row at 16x (asetrate 12672):
# a bird near 3.5 kHz that does remember - its intervals drift each time round.
# Right channel = left +0.28 Hz (afreqshift): every voice but the sub beats between the ears.
ffmpeg -hide_banner -y \
 -f g723_1 -i "data:,boolooooooooooonaeloooooboerooooozygaoooooooobuttooooobongooooobitoooooozachooooorindoooooooobilkooooojustooooobendooooooooboceooooooooooobothooooobilkooooozachoooooficeooooooooooozantoooooficeooooojapeooooozionoooooooooooooooooooo" \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:,boolooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooo" \
 -f g723_1 -i "data:," \
 -filter_complex "
 [0]asetrate=792,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=15.00,asplit[a0][b00];[b00]afreqshift=shift=0.28[b0];[a0]volume=0.85[l0];[b0]volume=0.6[r0];
 [1]asetrate=792,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=15.00,asplit[a1][b10];[b10]afreqshift=shift=0.28[b1];[a1]volume=0.85[l1];[b1]volume=0.6[r1];
 [2]asetrate=792,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=15.00,asplit[a2][b20];[b20]afreqshift=shift=0.28[b2];[a2]volume=0.85[l2];[b2]volume=0.6[r2];
 [3]asetrate=1584,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=7.50,asplit[a3][b30];[b30]afreqshift=shift=0.28[b3];[a3]volume=0.5[l3];[b3]volume=0.95[r3];
 [4]asetrate=1584,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=7.50,asplit[a4][b40];[b40]afreqshift=shift=0.28[b4];[a4]volume=0.95[l4];[b4]volume=0.5[r4];
 [5]asetrate=1584,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=7.50,asplit[a5][b50];[b50]afreqshift=shift=0.28[b5];[a5]volume=0.5[l5];[b5]volume=0.95[r5];
 [6]asetrate=1584,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=7.50,asplit[a6][b60];[b60]afreqshift=shift=0.28[b6];[a6]volume=0.95[l6];[b6]volume=0.5[r6];
 [7]asetrate=396,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=15.00,asplit[a7][b70];[b70]afreqshift=shift=0.28[b7];[a7]volume=0.7[l7];[b7]volume=0.7[r7];
 [8]asetrate=198,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=15.00,asplit[a8][b80];[b80]anull[b8];[a8]volume=0.7[l8];[b8]volume=0.7[r8];
 [9]asetrate=12672,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,adelay=50900,volume=1.80,asplit[a9][b90];[b90]afreqshift=shift=0.28[b9];[a9]volume=1.0[l9];[b9]volume=0.3[r9];
 [l0][l1][l2][l3][l4][l5][l6][l7][l8][l9]amix=inputs=10:normalize=0:duration=longest[L];
 [r0][r1][r2][r3][r4][r5][r6][r7][r8][r9]amix=inputs=10:normalize=0:duration=longest[R];
 [L][R]amerge=inputs=2,atrim=end=162,afade=t=out:st=150:d=12,volume=1.25,alimiter=level=0:limit=0.8:attack=20:release=200[out]" -map "[out]" "$@"
